## Why This Is Asked
This question tests the fundamental understanding of combining data structures to achieve O(1) operations while maintaining an ordering constraint. It evaluates knowledge of hash map + linked list patterns and eviction logic commonly used in caching systems.

## Key Concepts
- HashMap for O(1) key-to-node lookups
- Doubly linked list for maintaining recency order
- Node manipulation for constant-time recency updates
- Edge case handling: missing keys, capacity limits, and duplicate operations

## Code Example
```javascript
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key) {
    if (!this.cache.has(key)) return -1;
    const node = this.cache.get(key);
    this._moveToHead(node);
    return node.value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      node.value = value;
      this._moveToHead(node);
    } else {
      const newNode = { key, value, prev: null, next: null };
      this.cache.set(key, newNode);
      this._addToHead(newNode);
      if (this.cache.size > this.capacity) {
        this._removeTail();
      }
    }
  }

  _moveToHead(node) {
    this._removeNode(node);
    this._addToHead(node);
  }

  _addToHead(node) {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next.prev = node;
    this.head.next = node;
  }

  _removeNode(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _removeTail() {
    const node = this.tail.prev;
    this._removeNode(node);
    this.cache.delete(node.key);
  }
}
```

## Why This Is Asked
This question tests the ability to design a practical data structure and reason about block balancing in edit-heavy scenarios.

## Key Concepts
- **Sqrt decomposition**: Partition data into fixed-size blocks for efficient range queries
- **Per-block sums**: Enable O(1) block-level aggregation during rangeSum operations
- **Amortized balance**: Split/merge operations maintain block sizes within bounds, ensuring O(√n) amortized time per update
- **Edge-case handling**: Proper merge/split logic prevents pathological degradation

## Code Example
```javascript
class SqrtArray {
  constructor() {
    this.blocks = [];
    this.B = 2;
  }

  _getBlock(index) {
    let count = 0;
    for (const block of this.blocks) {
      if (index < count + block.length) return block;
      count += block.length;
    }
    throw new Error('Index out of bounds');
  }

  insertAt(index, value) {
    const block = this._getBlock(index);
    block.push(value);
    block.sum += value;
    if (block.length > 2 * this.B) this._split(block);
  }

  eraseAt(index) {
    const block = this._getBlock(index);
    block.splice(index, 1);
    block.sum -= value;
    if (block.length < this.B / 2) this._merge(block);
  }

  rangeSum(l, r) {
    let sum = 0;
    let count = 0;
    for (const block of this.blocks) {
      const blockStart = count;
      const blockEnd = count + block.length - 1;
      if (r < blockStart || l > blockEnd) { count += block.length; continue; }
      const start = Math.max(l, blockStart);
      const end = Math.min(r, blockEnd);
      if (start === blockStart && end === blockEnd) sum += block.sum;
      else for (let i = start; i <= end; i++) sum += block[i];
      count += block.length;
    }
    return sum;
  }

  _split(block) {
    const mid = Math.floor(block.length / 2);
    const newBlock = { arr: block.arr.splice(mid), sum: newBlock.arr.reduce((a,b)=>a+b,0) };
    block.sum = block.arr.reduce((a,b)=>a+b,0);
    const idx = this.blocks.indexOf(block);
    this.blocks.splice(idx + 1, 0, newBlock);
  }

  _merge(block) {
    const idx = this.blocks.indexOf(block);
    const neighbor = idx > 0 ? this.blocks[idx - 1] : this.blocks[idx + 1];
    const [small, big] = neighbor.length > block.length ? [block, neighbor] : [neighbor, block];
    big.arr.push(...small.arr);
    big.sum += small.sum;
    this.blocks.splice(this.blocks.indexOf(small), 1);
  }
}
```
